\usetikzlibrary{positioning, arrows.meta}
\begin{tikzpicture}[node distance=1.6cm, box/.style={draw, thick, rounded corners, minimum width=2cm, minimum height=0.9cm}]
  \node[box] (a) {Start};
  \node[box, right=of a] (b) {Process};
  \node[box, right=of b] (c) {Finish};
  \draw[-{Stealth}, thick] (a) -- (b);
  \draw[-{Stealth}, thick] (b) -- (c);
\end{tikzpicture}

\usepackage{pgfplots}
\pgfplotsset{compat=1.16}
\begin{tikzpicture}
  \begin{axis}[xlabel={Time $t$ (s)}, ylabel={Distance $d$ (m)}, grid=major, legend pos=north west]
    \addplot[domain=0:5, samples=30, blue, thick] {x^2};
    \addlegendentry{$d=t^2$}
  \end{axis}
\end{tikzpicture}

\usepackage{circuitikz}
\begin{tikzpicture}
  \draw (0,0) to[battery1, l=$V_s$] (0,3) to[R, l=$R_1$] (3,3) to[C, l=$C_1$] (3,0) -- (0,0);
\end{tikzpicture}

\usepackage{tikz-uml}
\begin{tikzpicture}
  \umlclass{Student}{name : String \\ id : Integer}{enrol() \\ withdraw()}
  \umlclass[x=6]{Module}{title : String \\ credits : Integer}{addStudent()}
  \umlclass[y=-4.5, x=3]{Lecturer}{name : String}{mark()}
  \umlassoc[mult1=0..*, mult2=1..*]{Student}{Module}
  \umlassoc[mult1=1, mult2=1..*]{Lecturer}{Module}
\end{tikzpicture}

\usepackage{contour}
\usetikzlibrary{shadings}
\begin{tikzpicture}
  \shade[top color=blue!70!black, bottom color=cyan!60!blue] (0,0) rectangle (6,3);
  \fill[yellow!90!orange] (4.5,2) circle (0.5);
  \fill[green!50!black] (0,0) -- (2,1.4) -- (4,0.6) -- (6,1.2) -- (6,0) -- cycle;
  \node[white] at (1.5,2.4) {\contour{blue!70!black}{Sky}};
  \node[white] at (3,0.4) {\contour{green!50!black}{Hills}};
  \node at (4.5,2) {\contour{yellow!90!orange}{Sun}};
\end{tikzpicture}

\begin{tikzpicture}[grow=right, level distance=3cm,
    level 1/.style={sibling distance=3.4cm}, level 2/.style={sibling distance=1.6cm},
    every node/.style={font=\small}]
  \node[draw, circle] {Start}
    child { node[draw, rounded corners] {Rain}
      child { node[draw, rounded corners] {Late} edge from parent node[above] {$0.6$} }
      child { node[draw, rounded corners] {On time} edge from parent node[below] {$0.4$} }
      edge from parent node[above] {$0.3$} }
    child { node[draw, rounded corners] {Dry}
      child { node[draw, rounded corners] {Late} edge from parent node[above] {$0.1$} }
      child { node[draw, rounded corners] {On time} edge from parent node[below] {$0.9$} }
      edge from parent node[below] {$0.7$} };
\end{tikzpicture}

\usepackage{pgfplots}
\pgfplotsset{compat=1.16}
\begin{tikzpicture}
  \begin{axis}[view={50}{30}, xlabel={$x$}, ylabel={$y$}, zlabel={$z$}, colormap/viridis]
    \addplot3[surf, domain=-2:2, samples=14] {exp(-x^2 - y^2)};
  \end{axis}
\end{tikzpicture}

\usetikzlibrary{mindmap}
\begin{tikzpicture}[mindmap, grow cyclic, concept color=blue!60!black, text=white,
    level 1/.append style={level distance=4cm, sibling angle=90},
    level 2/.append style={level distance=2.6cm, sibling angle=60}]
  \node[concept] {Learning}
    child[concept color=orange!80!black] { node[concept] {Memory} }
    child[concept color=green!50!black] { node[concept] {Practice} }
    child[concept color=red!70!black] { node[concept] {Feedback} }
    child[concept color=purple!70!black] { node[concept] {Motivation} };
\end{tikzpicture}

\usetikzlibrary{patterns.meta, decorations.pathmorphing, arrows.meta}
\begin{tikzpicture}
  \fill[pattern={Lines[angle=45, distance=4pt]}, pattern color=gray] (-0.4,-0.6) rectangle (0,1);
  \draw[thick] (0,-0.6) -- (0,1);
  \draw[thick] (0,0.2) -- (0.4,0.2);
  \draw[thick, decorate, decoration={coil, aspect=0.6, segment length=3mm, amplitude=3mm}] (0.4,0.2) -- (3.4,0.2);
  \draw[thick, fill=blue!15] (3.4,-0.3) rectangle (4.6,0.7);
  \node at (4,0.2) {$m$};
  \draw[-{Stealth}, thick, red] (4.6,0.2) -- (5.8,0.2) node[right] {$F$};
  \draw[Stealth-Stealth] (0,-0.9) -- (3.4,-0.9) node[midway, below] {$x$};
  \draw[thick] (-0.4,-0.6) -- (5.6,-0.6);
\end{tikzpicture}

\usetikzlibrary{automata, positioning, arrows.meta}
\begin{tikzpicture}[>={Stealth}, node distance=2.6cm, auto, thick]
  \node[state, initial] (q0) {$q_0$};
  \node[state, right=of q0] (q1) {$q_1$};
  \node[state, accepting, right=of q1] (q2) {$q_2$};
  \path[->] (q0) edge node {a} (q1)
            (q1) edge node {b} (q2)
            (q1) edge[loop above] node {a} ()
            (q0) edge[loop above] node {b} ()
            (q2) edge[bend left=40] node {a} (q0);
\end{tikzpicture}

\usepackage{tikz-3dplot}
\tdplotsetmaincoords{70}{110}
\begin{tikzpicture}[tdplot_main_coords, scale=1.2]
  \draw[->] (0,0,0) -- (3,0,0) node[anchor=north east] {$x$};
  \draw[->] (0,0,0) -- (0,3,0) node[anchor=north west] {$y$};
  \draw[->] (0,0,0) -- (0,0,3) node[anchor=south] {$z$};
  \tdplotsetcoord{P}{2.6}{50}{60}
  \draw[-stealth, very thick, red] (0,0,0) -- (P) node[above right] {$\mathbf{r}$};
  \draw[dashed, gray] (0,0,0) -- (Pxy);
  \draw[dashed, gray] (P) -- (Pxy);
  \tdplotdrawarc{(0,0,0)}{0.8}{0}{60}{anchor=north}{$\phi$}
\end{tikzpicture}
